begin;
insert into auth.users(id) values('cccccccc-cccc-4ccc-8ccc-ccccccccccc1'),('cccccccc-cccc-4ccc-8ccc-ccccccccccc2');
insert into public.s2a_groups(id,name,platform,subscription_type,daily_limit_usd,weekly_limit_usd,monthly_limit_usd) values
 ('cccccccc-cccc-4ccc-8ccc-ccccccccccc3','Subscription fixture','openai','subscription',0.0001,1,10);
insert into public.s2a_memberships values('cccccccc-cccc-4ccc-8ccc-ccccccccccc1','cccccccc-cccc-4ccc-8ccc-ccccccccccc3');
insert into public.s2a_accounts(group_id,name,platform,type,account_fingerprint,ciphertext,iv) values
 ('cccccccc-cccc-4ccc-8ccc-ccccccccccc3','Subscription fixture','openai','apikey','subscription-fixture','ciphertext','iv');
insert into public.s2a_keys(user_id,group_id,name,key_hash,key_prefix) values
 ('cccccccc-cccc-4ccc-8ccc-ccccccccccc1','cccccccc-cccc-4ccc-8ccc-ccccccccccc3','Subscription fixture',repeat('9',64),'fixture');
set local role service_role;
do $$ declare s jsonb; r jsonb; sid uuid; lease uuid; previous timestamptz; amount numeric; coupon jsonb; coupon_id uuid; before_term timestamptz; begin
 r:=public.s2a_acquire(repeat('9',64),'gpt-4.1',gen_random_uuid(),'{}',true,null,'{}');
 if r->>'error' is distinct from 'subscription_required' then raise exception 'missing subscription accepted: %',r; end if;
 s:=public.s2a_subscription_assign('cccccccc-cccc-4ccc-8ccc-ccccccccccc1','cccccccc-cccc-4ccc-8ccc-ccccccccccc3',30);
 sid:=(s->>'id')::uuid;
 if sid is null then raise exception 'assignment failed: %',s; end if;
 r:=public.s2a_subscription_assign('cccccccc-cccc-4ccc-8ccc-ccccccccccc1','cccccccc-cccc-4ccc-8ccc-ccccccccccc3',30);
 if r->>'id'<>sid::text or not (r->>'reused')::boolean then raise exception 'assignment not idempotent'; end if;
 r:=public.s2a_subscription_assign('cccccccc-cccc-4ccc-8ccc-ccccccccccc1','cccccccc-cccc-4ccc-8ccc-ccccccccccc3',31);
 if r->>'error' is distinct from 'subscription_assign_conflict' then raise exception 'assignment conflict ignored'; end if;
 r:=public.s2a_acquire(repeat('9',64),'gpt-4.1',gen_random_uuid(),'{}',true,null,'{}');lease:=(r->>'lease_id')::uuid;
 if lease is null then raise exception 'subscription required wallet funds: %',r; end if;
 perform public.s2a_finish(lease,200,'completed',100,10);
 perform public.s2a_finish(lease,200,'completed',100,10);
 if (select balance from public.s2a_wallets where user_id='cccccccc-cccc-4ccc-8ccc-ccccccccccc1')>0 or exists(select 1 from public.s2a_wallet_ledger where user_id='cccccccc-cccc-4ccc-8ccc-ccccccccccc1') then raise exception 'subscription debited wallet'; end if;
 select actual_cost into amount from public.s2a_usage where id=lease;
 if amount<>0.00028 or (select daily_usage_usd from public.s2a_subscriptions where id=sid)<>amount or (select weekly_usage_usd from public.s2a_subscriptions where id=sid)<>amount
  or (select subscription_id from public.s2a_usage where id=lease)<>sid or (select billing_mode from public.s2a_usage where id=lease)<>'token' or (select billing_type from public.s2a_usage where id=lease)<>1 then raise exception 'subscription settlement mismatch'; end if;
 r:=public.s2a_acquire(repeat('9',64),'gpt-4.1',gen_random_uuid(),'{}',true,null,'{}');
 if r->>'error' is distinct from 'daily_limit_exceeded' then raise exception 'daily quota ignored: %',r; end if;
 update public.s2a_subscriptions set daily_window_start=now()-interval '2 days',weekly_window_start=now()-interval '8 days',monthly_window_start=now()-interval '31 days',daily_usage_usd=1,weekly_usage_usd=1,monthly_usage_usd=1 where id=sid;
 perform public.s2a_subscription_refresh(sid);
 if exists(select 1 from public.s2a_subscriptions where id=sid and (daily_usage_usd<>0 or weekly_usage_usd<>0 or monthly_usage_usd<>0)) then raise exception 'expired windows not reset'; end if;
 update public.s2a_subscriptions set daily_usage_usd=1,weekly_usage_usd=2,monthly_usage_usd=3 where id=sid;
 perform public.s2a_subscription_mutate(sid,'reset_quota',null,'{"daily":true}');
 if (select daily_usage_usd from public.s2a_subscriptions where id=sid)<>0 or (select weekly_usage_usd from public.s2a_subscriptions where id=sid)<>2 then raise exception 'manual reset affected wrong windows'; end if;
 select expires_at into previous from public.s2a_subscriptions where id=sid;
 r:=public.s2a_subscription_bulk('cccccccc-cccc-4ccc-8ccc-ccccccccccc2','extend-fixture',array[sid],'extend',2);
 if r->>'success_count'<>'1' then raise exception 'bulk extend failed: %',r; end if;
 perform public.s2a_subscription_bulk('cccccccc-cccc-4ccc-8ccc-ccccccccccc2','extend-fixture',array[sid],'extend',2);
 if (select expires_at from public.s2a_subscriptions where id=sid)<>previous+interval '2 days' then raise exception 'bulk retry extended twice'; end if;
 r:=public.s2a_subscription_bulk('cccccccc-cccc-4ccc-8ccc-ccccccccccc2','extend-fixture',array[sid],'extend',3);
 if r->>'error' is distinct from 'idempotency_conflict' then raise exception 'bulk conflict ignored'; end if;
 perform public.s2a_subscription_mutate(sid,'revoke');
 r:=public.s2a_acquire(repeat('9',64),'gpt-4.1',gen_random_uuid(),'{}',true,null,'{}');
 if r->>'error' is distinct from 'subscription_required' then raise exception 'revoked subscription accepted'; end if;
 perform public.s2a_subscription_mutate(sid,'restore');
 r:=public.s2a_subscription_list('cccccccc-cccc-4ccc-8ccc-ccccccccccc1',null,'active');
 if r->>'total'<>'1' then raise exception 'subscription listing mismatch: %',r; end if;
 begin update public.s2a_groups set subscription_type='standard' where id='cccccccc-cccc-4ccc-8ccc-ccccccccccc3';raise exception 'billing mode changed with live subscriptions';exception when unique_violation then null;end;
 select expires_at into before_term from public.s2a_subscriptions where id=sid;
 coupon:=public.s2a_redeem_generate(1,'subscription',1,null,'private','cccccccc-cccc-4ccc-8ccc-ccccccccccc3',5)->0;
 coupon_id:=(coupon->>'id')::uuid;
 r:=public.s2a_redeem_use('cccccccc-cccc-4ccc-8ccc-ccccccccccc1',coupon->>'code');
 if r ? 'error' or r->'subscription'->>'id'<>sid::text then raise exception 'subscription coupon failed: %',r; end if;
 if (select expires_at from public.s2a_subscriptions where id=sid)<>before_term+interval '5 days' then raise exception 'coupon did not extend term'; end if;
 r:=public.s2a_redeem_use('cccccccc-cccc-4ccc-8ccc-ccccccccccc1',coupon->>'code');
 if r->>'error' is distinct from 'redeem_code_used' then raise exception 'subscription coupon reused'; end if;
 select expires_at into before_term from public.s2a_subscriptions where id=sid;
 r:=public.s2a_redeem_create_and_use('cccccccc-cccc-4ccc-8ccc-ccccccccccc1','fixed-subscription-order','subscription',1,null,'','cccccccc-cccc-4ccc-8ccc-ccccccccccc3',2);
 if r ? 'error' then raise exception 'fixed subscription order failed: %',r; end if;
 perform public.s2a_redeem_create_and_use('cccccccc-cccc-4ccc-8ccc-ccccccccccc1','fixed-subscription-order','subscription',1,null,'','cccccccc-cccc-4ccc-8ccc-ccccccccccc3',2);
 if (select expires_at from public.s2a_subscriptions where id=sid)<>before_term+interval '2 days' then raise exception 'fixed subscription order extended twice'; end if;
 r:=public.s2a_redeem_create_and_use('cccccccc-cccc-4ccc-8ccc-ccccccccccc1','fixed-subscription-order','subscription',1,null,'','cccccccc-cccc-4ccc-8ccc-ccccccccccc3',3);
 if r->>'error' is distinct from 'redeem_code_conflict' then raise exception 'coupon duration conflict ignored'; end if;
 coupon:=public.s2a_redeem_generate(1,'subscription',1,null,'private','cccccccc-cccc-4ccc-8ccc-ccccccccccc3',-1)->0;
 r:=public.s2a_redeem_use('cccccccc-cccc-4ccc-8ccc-ccccccccccc1',coupon->>'code');
 if r ? 'error' or (select expires_at from public.s2a_subscriptions where id=sid)<>before_term+interval '1 day' then raise exception 'negative subscription coupon failed: %',r; end if;
 update public.s2a_subscriptions set expires_at=now()-interval '1 second',weekly_window_start=now()-interval '8 days',weekly_usage_usd=1 where id=sid;
 perform public.s2a_subscription_refresh(sid);
 r:=public.s2a_acquire(repeat('9',64),'gpt-4.1',gen_random_uuid(),'{}',true,null,'{}');
 if r->>'error' is distinct from 'subscription_inactive' then raise exception 'expired subscription accepted'; end if;
 perform public.s2a_subscription_assign('cccccccc-cccc-4ccc-8ccc-ccccccccccc1','cccccccc-cccc-4ccc-8ccc-ccccccccccc3',30);
 if (select weekly_usage_usd from public.s2a_subscriptions where id=sid)<>0 then raise exception 'renewal retained expired usage'; end if;
 delete from public.s2a_subscriptions where id=sid;
 if (select billing_type from public.s2a_usage where id=lease)<>1 or (select subscription_id from public.s2a_usage where id=lease) is not null then raise exception 'historical funding source changed on subscription deletion'; end if;
end $$;
rollback;
